previewCss:
.darma-loader-darma-b16-gel-electrophoresis { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #67e8f9); width: var(--loader-size, 122px); height: calc(var(--loader-size, 122px) * .72); position: relative; overflow: hidden; border-radius: 6px; background: color-mix(in srgb, var(--accent) 12%, transparent); }
.darma-loader-darma-b16-gel-electrophoresis .darma-loader-darma-b16-gel-electrophoresis__well { position: absolute; left: 0; right: 0; top: 6%; height: 7%; background: repeating-linear-gradient(90deg, transparent 0 4%, color-mix(in srgb, #0f172a 45%, transparent) 0 14%, transparent 0 18%); }
.darma-loader-darma-b16-gel-electrophoresis span { position: absolute; top: 14%; width: 10%; height: 5%; border-radius: 2px; background: var(--accent-2); box-shadow: 0 0 8px color-mix(in srgb, var(--accent-2) 70%, transparent); animation: darma-loader-darma-b16-gel-electrophoresis-gel-run calc(var(--loader-speed, 1s) * 3.4) cubic-bezier(.25, .5, .4, 1) infinite; }
.darma-loader-darma-b16-gel-electrophoresis span:nth-of-type(1) { left: 5%; --end: calc(var(--loader-size, 122px) * .32); }
.darma-loader-darma-b16-gel-electrophoresis span:nth-of-type(2) { left: 21%; --end: calc(var(--loader-size, 122px) * .19); animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b16-gel-electrophoresis span:nth-of-type(3) { left: 37%; --end: calc(var(--loader-size, 122px) * .4); animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b16-gel-electrophoresis span:nth-of-type(4) { left: 53%; --end: calc(var(--loader-size, 122px) * .25); animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b16-gel-electrophoresis span:nth-of-type(5) { left: 69%; --end: calc(var(--loader-size, 122px) * .46); animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b16-gel-electrophoresis span:nth-of-type(6) { left: 85%; --end: calc(var(--loader-size, 122px) * .13); animation-delay: calc(var(--loader-speed, 1s) * .5); }
@keyframes darma-loader-darma-b16-gel-electrophoresis-gel-run { 0% { transform: translateY(0); opacity: 0; } 10% { opacity: 1; } 72%, 88% { transform: translateY(var(--end, 40px)); opacity: 1; } 100% { transform: translateY(var(--end, 40px)); opacity: 0; } }

